[ 242 ]
public async Task<ArtistResponse> GetArtistAsync(GetArtistRequest
request)
{
if (request?.Id == null) throw new ArgumentNullException();
var result = await _artistRepository.GetAsync(request.Id);
return result == null ? null : _artistMapper.Map(result);
}
public async Task<IEnumerable<ItemResponse>>
GetItemByArtistIdAsync(GetArtistRequest request)
{
if (request?.Id == null) throw new ArgumentNullException();
var result = await
_itemRepository.GetItemByArtistIdAsync(request.Id);
return result.Select(_itemMapper.Map);
}
public async Task<ArtistResponse> AddArtistAsync(AddArtistRequest
request)
{
var item = new Entities.Artist {ArtistName =
request.ArtistName};
var result = _artistRepository.Add(item);
await _artistRepository.UnitOfWork.SaveChangesAsync();
return _artistMapper.Map(result);
}
}
The implementation represents the methods already defined in the IArtistService
interface. It is quite easy to understand the purpose of the methods by looking at
their signatures.
The GetAsync method invokes the IArtistRepository dependency to map and retrieve
the result in an ArtistResponse object. GetItemByArtistIdAsync executes the
corresponding method with the same name defined in the IItemRepository interface.
Finally, AddArtistAsync executes the Add method defined in the IArtistRepository
interface and executes the UnitOfWork.SaveChangesAsync method to apply the changes
to the data source, and then map the resulting data.
